const getStructure=()=>import('./structure.js');
let providerState={configured:false,checked:false},selectedSentenceId=null,regionMode=false,previewHighlight=null,regionDraft=null,readerResizeObserver=null,updateReaderSize=null;
let settingsBusy=false;
let editorMode='auto';
