const names={draft:'草稿',published:'已上架',hidden:'已隐藏',withdrawn:'已下架'};
let books=[],book=null,tab='info',pageId=null,filter='all',search='',sort='updated',saveTimer=null,saveChain=Promise.resolve(),saveError=null,pendingWrites=0,working=false,imageBusy=false,pause=false,job='',previewSource='draft',readerPage=0,readerSentence=0,readerPlaying=false,readerAudio=null,crop={x:0,y:0,w:100,h:100},imageCache=null,previewInfo=null,perspective=null;
let urls=new WeakMap();const viewUrls=new Set();
const uid=prefix=>store.newId(prefix),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=b=>{if(!b)return '';if(typeof b==='string')return b;if(!urls.has(b)){const created=URL.createObjectURL(b);urls.set(b,created);viewUrls.add(created)}return urls.get(b)};
const date=v=>new Date(v).toLocaleDateString('zh-CN',{month:'short',day:'numeric'});
const currentPage=()=>book?.draft?.pages.find(p=>p.id===pageId);
const metadata=()=>book.draft.metadata;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function showModal(html){modal.classList.remove('settings-modal');$('#modalBody').innerHTML=html;if(!modal.open)modal.showModal()}
function closeModal(){if(settingsBusy&&modal.classList.contains('settings-modal'))return toast('正在加密保存，请稍候');if(modal.classList.contains('settings-modal'))$('#modalBody').innerHTML='';modal.classList.remove('settings-modal');modal.close()}
async function confirmAction(title,text,action,label='确认'){showModal(`<h2>${escape(title)}</h2><p class="muted">${escape(text)}</p><div class="modal-actions"><button data-close>取消</button><button class="primary" id="confirmAction">${escape(label)}</button></div>`);$('#confirmAction').onclick=async()=>{closeModal();try{await action()}catch(e){fail(e)}}}
function fail(e){console.error(e);toast(e.message||String(e))}
function refreshTTSFeedback(){if(!ttsActivity)return;const local=document.querySelector(`[data-tts-status="${ttsActivity.sentenceId}"]`);if(local){local.hidden=false;local.textContent=ttsActivity.text;local.dataset.state=ttsActivity.status}const row=document.querySelector(`[data-audio-sentence="${ttsActivity.sentenceId}"]`);if(row){row.setAttribute('aria-busy',String(ttsActivity.status==='working'));const button=row.querySelector('[data-sact=tts]');if(button){const sentence=currentPage()?.sentences.find(s=>s.id===ttsActivity.sentenceId);button.textContent=ttsActivity.status==='working'?'正在处理…':sentence?.audio?'重新配音':'生成配音'}}}
function setJob(text){job=text;const el=$('#job');if(el){el.hidden=false;let message=el.querySelector('.job-message');if(!message){message=document.createElement('span');message.className='job-message';for(const node of [...el.childNodes])if(node.nodeType===3)node.remove();el.prepend(message)}message.textContent=text}if(ttsActivity?.status==='working'){ttsActivity.text=text;refreshTTSFeedback()}}

function saveSoon(){saveError=null;$('#saveState').textContent='有修改 · 正在保存…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(fail),450)}
function persist(){clearTimeout(saveTimer);saveTimer=null;if(!book)return saveChain;const target=book;pendingWrites++;saveChain=saveChain.catch(()=>{}).then(async()=>{try{const saved=await store.saveBook(target);target.revision=saved.revision;target.updatedAt=saved.updatedAt;saveError=null;$('#saveState').textContent='✓ 已保存到当前浏览器';return saved}catch(e){saveError=e;$('#saveState').textContent='保存失败 · 点击重试，请勿刷新';throw e}finally{pendingWrites--}});return saveChain}
async function flush(){for(;;){if(saveTimer)await persist();const observed=saveChain;await observed;if(!saveTimer&&observed===saveChain)break}if(saveError)throw saveError}
async function transition(next){await flush();book=await store.saveBook(next);saveError=null;$('#saveState').textContent='✓ 已保存到当前浏览器';await refreshBooks();render()}
async function refreshBooks(){books=await store.listBooks();$('#bookCount').textContent=books.length}
async function library(){if(working){toast('请先等待当前处理结束，或在本页完成后暂停');return}stopReader();await flush();book=null;await refreshBooks();renderLibrary()}
async function openBook(id,nextTab='info'){if(working)return toast('请先完成当前处理');await flush();book=await store.getBook(id);perspective=null;editorMode='auto';if(working)return toast('请先完成当前处理');if(!book.draft&&nextTab!=='preview'){book=store.beginEdit(book);await persist()}tab=nextTab;pageId=book.draft?.pages[0]?.id;readerPage=0;readerSentence=0;crop={x:0,y:0,w:100,h:100};render()}
async function create(){if(working)return toast('请先完成当前处理');await flush();showModal(`<div class="eyebrow">A NEW STORY</div><h2>让下一本故事开始</h2><p class="muted">先取一个书名，照片和其他信息可以随后补充。</p><label class="field">绘本书名<input id="newTitle" placeholder="例如：The Very Hungry Caterpillar" maxlength="200"></label><div class="modal-actions"><button data-close>取消</button><button class="primary" id="createConfirm">创建绘本</button></div>`);$('#newTitle').focus();$('#createConfirm').onclick=async()=>{const title=$('#newTitle').value.trim();if(!title){$('#newTitle').focus();return toast('请填写绘本书名')}try{book=await store.createBook(title);tab='pages';editorMode='auto';pageId=null;closeModal();await refreshBooks();render();toast('新绘本已创建，可以开始导入照片')}catch(e){fail(e)}}}
function releaseView(){readerResizeObserver?.disconnect();readerResizeObserver=null;updateReaderSize=null;for(const u of viewUrls)URL.revokeObjectURL(u);viewUrls.clear();urls=new WeakMap();if(imageCache){imageCache.close();imageCache=null}}
function renderLibrary(){document.body.classList.remove('editing-book');stopReader();releaseView();document.title='绘本书库 · 绘本工作室';$('#breadcrumb').textContent='工作空间 / 绘本书库';$('#libraryNav').classList.add('active');const counts={published:0,draft:0,hidden:0,withdrawn:0};books.forEach(b=>counts[b.status]++);let shown=books.filter(b=>(filter==='all'||b.status===filter)&&((b.draft?.metadata.title||b.title)+' '+(b.draft?.metadata.author??b.author)+' '+(b.draft?.metadata.tags||b.tags).join(' ')).toLowerCase().includes(search.toLowerCase()));shown.sort((a,b)=>sort==='title'?(a.draft?.metadata.title||a.title).localeCompare(b.draft?.metadata.title||b.title):sort==='sort'?((a.draft?.metadata.sort??a.sort)-(b.draft?.metadata.sort??b.sort)):new Date(b.updatedAt)-new Date(a.updatedAt));app.innerHTML=`<header class="hero"><div><div class="eyebrow">YOUR STORIES, BEAUTIFULLY MADE</div><h1>每一本，都值得被听见。</h1><p>从一张照片开始，把好故事放进孩子的书架。</p></div><button class="primary" data-act="new">＋ 制作新绘本</button></header><div class="stats"><div class="stat"><b>${books.length}</b><span>全部绘本</span></div><div class="stat"><b>${counts.published}</b><span>已上架</span></div><div class="stat"><b>${books.filter(b=>b.draft).length}</b><span>制作 / 修改中</span></div><div class="stat"><b>${counts.hidden+counts.withdrawn}</b><span>隐藏与下架</span></div></div><div class="toolbar"><div class="filters">${[['all','全部'],['published','已上架'],['draft','草稿'],['hidden','已隐藏'],['withdrawn','已下架']].map(([v,l])=>`<button class="filter ${filter===v?'active':''}" data-filter="${v}">${l}</button>`).join('')}</div><div class="search-sort"><input id="search" placeholder="搜索书名、作者或标签" value="${escape(search)}" aria-label="搜索绘本"><select id="sort" aria-label="排序"><option value="updated" ${sort==='updated'?'selected':''}>最近修改</option><option value="title" ${sort==='title'?'selected':''}>书名排序</option><option value="sort" ${sort==='sort'?'selected':''}>书架顺序</option></select></div></div><section class="grid">${shown.map(b=>`<article class="book-card"><div class="cover-wrap" data-open="${b.id}"><span class="status ${b.status}">${names[b.status]}</span>${b.cover||b.draft?.metadata.cover?`<img alt="${escape(b.draft?.metadata.title||b.title)} 封面" src="${url(b.draft?.metadata.cover||b.cover)}">`:'<span class="muted">等待一张封面</span>'}</div><div class="book-body"><h3>${escape(b.draft?.metadata.title||b.title)}</h3><div class="book-meta">${escape((b.draft?.metadata.author??b.author)||'作者未填写')} · ${(b.draft||b.published)?.pages.length||0} 个阅读画面${b.isDemo?' · 演示样本':''}</div>${b.draft&&b.published?'<div class="draft-hint">● 有尚未发布的修改</div>':'<div class="draft-hint">'+(b.isDemo?'本地样本，不是完整线上绘本':'&nbsp;')+'</div>'}<div class="card-bottom"><span class="book-meta">${date(b.updatedAt)}</span><div class="card-actions"><button data-open="${b.id}">编辑</button>${b.published?`<button data-preview="${b.id}">预览</button><button data-manage="${b.id}">管理</button>`:''}</div></div></div></article>`).join('')||'<div class="empty"><h3>这里还有很多故事的位置</h3><p>创建一本绘本，或调整搜索条件。</p><button data-act="new">＋ 制作新绘本</button></div>'}</section><p class="hint" style="margin-top:25px">本地演示环境 · “上架”只影响这个浏览器中的书库，不会修改线上阅读端。建议定期导出工作室备份。</p>`;$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;renderLibrary();$('#search').focus();$('#search').setSelectionRange(pos,pos)};$('#sort').onchange=e=>{sort=e.target.value;renderLibrary()}}
function render(){if(!book)return renderLibrary();document.body.classList.add('editing-book');stopReader();releaseView();$('#libraryNav').classList.remove('active');$('#breadcrumb').textContent=`绘本书库 / ${book.draft?.metadata.title||book.title}`;document.title=`${book.draft?.metadata.title||book.title} · 绘本工作室`;app.innerHTML=`<header class="editor-head"><div><div class="eyebrow">BOOK STUDIO / ${book.isDemo?'DEMO SAMPLE':'WORK IN PROGRESS'}</div><h1>${escape(book.draft?.metadata.title||book.title)}</h1><span class="status ${book.status}">${names[book.status]}</span> <span class="hint">${book.published?'修改保存在草稿中，原发布版本继续可用':'尚未发布 · 制作进度自动保存'}</span></div><div class="editor-actions"><button data-act="library">返回书库</button><button data-act="previewDraft">预览草稿</button>${tab==='preview'?`<button class="primary" data-act="publish" ${!book.draft?'disabled':''}>检查并发布到本地 ↗</button>`:''}</div></header>${book.isDemo?'<div class="notice">DROP 演示样本仅包含部分公开页面，用于操作验证；未导入线上完整书库与配音。</div>':''}<div class="tabs">${[['info','01　基本信息'],['pages','02　制作页面'],['preview','03　预览与发布']].map(([v,l])=>`<button class="tab ${tab===v?'active':''}" data-tab="${v}">${l}</button>`).join('')}</div><div id="workspace">${tab==='info'?infoHTML():tab==='pages'?pagesHTML():previewHTML()}</div>`;bindInputs();if(tab==='pages'&&currentPage())drawCanvas().catch(fail);if(tab==='preview')bindReader()}
function infoHTML(){const m=metadata();return `<div class="panel"><div class="section-title"><h2>故事的第一印象</h2><span class="hint">只有书名和封面为必填</span></div><div class="metadata-layout"><div class="cover-picker">${m.cover?`<img src="${url(m.cover)}" alt="草稿封面">`:'<span class="muted">添加绘本封面</span>'}<button data-act="cover">${m.cover?'更换封面':'上传封面'}</button><span class="hint">也可以将任意页面设为封面</span></div><div class="form-grid">${[['title','书名 *'],['author','作者'],['series','所属系列'],['age','适读年龄'],['tags','主题标签'],['sort','书架顺序']].map(([k,l])=>`<label class="field">${l}<input data-meta="${k}" ${k==='sort'?'type="number"':''} value="${escape(k==='tags'?m.tags.join('，'):m[k])}" placeholder="${k==='tags'?'用逗号分隔，例如：情绪，友谊':'选填'}"></label>`).join('')}<label class="field full">绘本简介<textarea data-meta="description" rows="4" placeholder="简单介绍这个故事…">${escape(m.description)}</textarea></label></div></div></div><div class="panel"><h3>版本与可见范围</h3><p class="hint">${book.published?'已有独立发布版本。这里的修改不会影响发布版本，确认后再次发布即可统一更新。':'当前仅有制作草稿，发布后会建立独立版本。'}</p>${book.published?`<button data-act="previewPublished">查看当前发布版本</button> <button data-act="manage">管理上架状态</button>`:''}<div class="danger-zone"><button class="danger small" data-act="deleteBook">删除这本绘本</button><span class="hint">　只删除当前浏览器内的内容</span></div></div>`}
function rectified(p){return structure.isPageRectified(p)}
function validRegions(s){try{structure.validateRegions(s.regions);return true}catch{return false}}
function sentenceReady(s,p){return structure.isSentenceReady(s,p)}
function selectedSentence(){return currentPage()?.sentences.find(s=>s.id===selectedSentenceId)}
function pageReviewed(p){return rectified(p)&&p.analysisReviewed===true&&p.analysisRevision===(p.imageRevision||0)&&p.sentences.every(s=>sentenceReady(s,p))}
function pendingAudio(p){return p.sentences.filter(s=>s.includeInNarration!==false&&sentenceReady(s,p)&&(!s.audio||s.audioText!==s.en))}
function pageStage(p){if(!rectified(p))return 0;if(!pageReviewed(p))return p.sentences.length||p.analysisRevision===(p.imageRevision||0)?2:1;return pendingAudio(p).length?3:4}
function workspaceMode(p){if(perspective?.pageId===p.id)return 'image';if(editorMode!=='auto')return editorMode;const stage=pageStage(p);return stage===0?'image':stage<3?'text':'audio'}
function stageLabel(p){return ['待校正','待分析','待审核','待配音','已完成'][pageStage(p)]}
function sentenceLabelHTML(s,i,p){const ready=sentenceReady(s,p);return `<span>句子 ${String(i+1).padStart(2,'0')}</span><span class="review-badge ${ready?'reviewed':'pending'}">${ready?'✓ 已审核':'○ 待审核'}</span>${s.audio&&s.audioText!==s.en?'<span class="audio-stale">待重配</span>':''}`}
function invalidateSentence(s,p){
 s.reviewed=false;p.analysisReviewed=false;p.textRevision=(p.textRevision||0)+1;
 const row=document.querySelector(`[data-sentence="${s.id}"]`);
 if(row){const label=row.querySelector('.sentence-top>.plain');if(label)label.innerHTML=sentenceLabelHTML(s,p.sentences.indexOf(s),p);const review=row.querySelector('[data-sact=review]');if(review)review.textContent=returnToAudioSentenceId===s.id?'确认并返回本句配音':'确认本句文字与定位';}
 const next=$('#stageAction');if(next)next.innerHTML=stageActionHTML(p,workspaceMode(p));
 const workflow=$('#pageWorkflow');if(workflow)workflow.innerHTML=workflowHTML(p);
 const heading=$('#pageStageLabel');if(heading)heading.textContent=stageLabel(p);
 const count=$('#sentenceReviewCount');if(count)count.textContent=`${p.sentences.filter(x=>sentenceReady(x,p)).length} / ${p.sentences.length} 句已审核`;
 job='';const status=$('#job');if(status)status.hidden=true;
 const progress=$('#pageProgressSummary');if(progress)progress.textContent=`${book.draft.pages.length} 个页面 · ${book.draft.pages.filter(x=>pageStage(x)===4).length} 页已完成`;
 const pageButton=document.querySelector(`[data-page="${p.id}"]`);if(pageButton)pageButton.setAttribute('aria-label',`第 ${book.draft.pages.indexOf(p)+1} 页，${stageLabel(p)}`);
 const thumb=document.querySelector(`[data-page="${p.id}"] span`);if(thumb)thumb.textContent=`${String(book.draft.pages.indexOf(p)+1).padStart(2,'0')} · ${stageLabel(p)}`;
}
function workflowHTML(p){if(!p)return '';const stage=pageStage(p);return `<span class="status" id="pageStageLabel">${stageLabel(p)}</span><span class="progress-context">${stage===4?'可预览整本':`第 ${stage+1} / 5 步`}</span>`}

function stageActionHTML(p,mode){
 const stage=pageStage(p),candidate=perspective?.pageId===p.id;
 let title,description,action,label;
 if(mode==='image'){
  if(candidate){title='检查四角，确认后应用';description='拖动图上的四个圆点，让边框贴合书页。应用后进入文字与点读。';action='applyBorder';label='确认四角并应用透视裁剪'}
  else if(!rectified(p)){title='先把书页摆正';description='让 AI 建议四角，再由你确认。已经端正的扫描图也可以直接确认使用。';action='multimodalCorners';label='AI 建议书页四角'}
  else{title='图片已确认，可以分析正文';description='后续文字框均以这张校正图为准。再次修改图片后，需要重新审核。';action='textWorkspace';label='继续：文字与点读'}
 }else if(mode==='text'){
  if(!rectified(p)){title='先完成图片校正';description='确认校正图后，才能分析、定位和审核文字。';action='imageWorkspace';label='返回图片校正'}
  else if(stage===1){title='让 AI 理解这一页';description='一次生成英文分句、中文翻译与文字框，结果需要你逐项核对。';action='analyzePage';label='AI 分析本页'}
  else if(!pageReviewed(p)){title=p.sentences.length?'核对文字、翻译与点读位置':'确认这一页是否无需文案';description=p.sentences.length?(p.sentences.every(s=>sentenceReady(s,p))?'所有句子已逐句审核。请再确认本页朗读顺序，即可批量配音。':'点击句子或图上的文字框检查位置。全部核对后确认本页，进入配音。'):'AI 结果和纯插画页都需要人工确认；有正文时可添加句子。';action='reviewPage';label=p.sentences.length?'整页审核完成 → 配音':'确认无需文案 → 配音'}
  else{title='本页文字已审核';description='可以进入配音；继续编辑文字或位置会让本页重新进入待审核。';action='audioWorkspace';label='继续：本地配音'}
 }else{
  if(!pageReviewed(p)){title='先完成本页人工审核';description='整页确认后可批量配音；已逐句确认的内容可直接使用下方的单句配音按钮。';action=rectified(p)?'textWorkspace':'imageWorkspace';label=rectified(p)?'返回文字审核':'返回图片校正'}
  else if(pendingAudio(p).length){title=`还有 ${pendingAudio(p).length} 句等待配音`;description='在当前设备生成英文语音。已有且仍有效的音频会自动保留。';action='pageTTS';label='生成本页待配音'}
  else{const next=book.draft.pages.find(x=>x.id!==p.id&&pageStage(x)!==4);title='本页已准备好';description=next?'可以继续制作其他未完成页面，也可以随时预览草稿。':'所有页面已完成，可以试听点读，再检查封面与发布条件。';action=next?'nextPendingPage':'previewDraft';label=next?'继续下一待办页':'预览整本绘本'}
 }
 return `<div class="stage-copy"><span class="eyebrow">当前步骤</span><h3>${title}</h3><p>${description}</p></div><button class="primary" data-act="${action}" ${working?'disabled':''}>${label}</button>`
}
function pageMoreHTML(p,pages){return `<details class="tool-disclosure page-more"><summary>页面管理</summary><div class="tool-content"><div class="page-tools"><button data-act="pageUp" ${pages.indexOf(p)===0||working?'disabled':''}>前移一页</button><button data-act="pageDown" ${pages.indexOf(p)===pages.length-1||working?'disabled':''}>后移一页</button><button data-act="setCover" ${working?'disabled':''}>设为封面</button><button data-act="replace" ${working?'disabled':''}>补拍换图</button><button data-act="splitPage" ${working?'disabled':''}>拆为左右两页</button><button data-act="mergePage" ${pages.indexOf(p)===pages.length-1||working?'disabled':''}>与后一页合并</button><button class="danger" data-act="deletePage" ${working?'disabled':''}>删除本页</button></div></div></details>`}
function imageToolsHTML(p){return `<div class="secondary-actions"><button data-act="manualBorder" ${working?'disabled':''}>手动选四角</button>${!rectified(p)&&!perspective?`<button data-act="confirmRectification" ${working?'disabled':''}>图片已端正，直接确认</button>`:''}</div><details class="tool-disclosure"><summary>更多图片工具 <span>旋转、裁剪、恢复原图</span></summary><div class="tool-content"><p class="hint">修改图片会使已有文字定位与审核失效；原图始终保留。</p><div class="page-tools">${rectified(p)?`<button data-act="multimodalCorners" ${working?'disabled':''}>重新让 AI 建议四角</button>`:''}<button data-act="rotate" ${working?'disabled':''}>旋转 90°</button><button data-act="resetImage" ${!p.original||working?'disabled':''}>恢复原图</button><button data-act="detectBorder" ${working?'disabled':''}>本地检测四角</button></div><div class="crop-fields">${[['x','左 %'],['y','上 %'],['w','宽 %'],['h','高 %']].map(([k,l])=>`<label>${l}<input type="number" min="0" max="100" data-crop="${k}" value="${crop[k]}" ${working?'disabled':''}></label>`).join('')}<button data-act="crop" ${working?'disabled':''}>应用裁剪</button><button data-act="clearCrop" ${working?'disabled':''}>清除选区</button><label>角度 °<input id="fineAngle" type="number" min="-15" max="15" step="0.5" value="0" ${working?'disabled':''}></label><button data-act="fineRotate" ${working?'disabled':''}>应用角度</button></div></div></details>`}
function textToolsHTML(p){return `<details class="tool-disclosure"><summary>更多文字工具 <span>重新分析、JSON、本地 OCR</span></summary><div class="tool-content"><div class="page-tools"><button data-act="analyzePage" ${working||!rectified(p)?'disabled':''}>重新 AI 分析本页</button><button data-act="importAnalysis" ${working||!rectified(p)?'disabled':''}>导入结构化 JSON</button><button data-act="exportAnalysis" ${working?'disabled':''}>导出本页数据</button><button data-act="ocr" ${working||!rectified(p)?'disabled':''}>本地 OCR 本页</button><button data-act="batchOCR" ${working?'disabled':''}>本地 OCR 未识别页</button></div><p class="hint">JSON 使用当前校正图的 0–1 归一化坐标。本地 OCR 仅提取文字行；中文、顺序、定位仍需人工补齐和审核。</p>${p.ocr?`<details><summary>原始 OCR 行</summary><div class="ocr-lines">${p.ocr.map((x,i)=>`${i+1}. [${Math.round(x.score*100)}%] ${escape(x.text)}`).join('\n')}</div></details>`:''}</div></details>`}
function regionTaskHTML(p){return `<div class="region-task"><div><b>为句子 ${p.sentences.findIndex(s=>s.id===selectedSentenceId)+1} 添加文字框</b><p>拖动新增，可连续加框；已有框可在「修改已有框」中调整。</p></div><button data-act="stopRegion">结束画框并返回句子</button></div>`}
function pagesHTML(){
 const pages=book.draft.pages,p=currentPage(),mode=p?workspaceMode(p):'image';
 return `<div class="studio-toolbar"><span id="pageProgressSummary">${pages.length} 个页面 · ${pages.filter(x=>pageStage(x)===4).length} 页已完成</span><div><button data-act="import" ${working?'disabled':''}>＋ 导入照片</button><details class="tool-disclosure compact"><summary>更多</summary><div class="tool-content"><button data-act="sample" ${working?'disabled':''}>添加示例图片</button></div></details></div></div>${working||job?`<div class="progress-line" id="job" role="status">${escape(job||'正在处理，请稍候…')}${working&&!imageBusy?'<button data-act="pause">本句完成后暂停</button>':''}</div>`:'<div id="job" class="progress-line" role="status" hidden></div>'}<div class="studio"><aside class="page-rail" aria-label="绘本页面">${pages.map((x,i)=>`<button class="page-thumb ${x.id===pageId?'active':''}" data-page="${x.id}" ${working?'disabled':''} aria-label="第 ${i+1} 页，${stageLabel(x)}"><img src="${url(x.image)}" alt="第 ${i+1} 页"><span>${String(i+1).padStart(2,'0')} · ${stageLabel(x)}</span></button>`).join('')}</aside><section class="studio-main">${p?`<div class="page-heading"><div class="page-heading-title"><h2>第 ${pages.indexOf(p)+1} 页</h2><div class="page-progress" id="pageWorkflow" aria-label="当前页面制作进度">${workflowHTML(p)}</div></div>${pageMoreHTML(p,pages)}</div><nav class="workspace-tabs" aria-label="本页工作区">${[['image','图片校正'],['text','文字与点读'],['audio','本地配音']].map(([key,label],i)=>`<button data-mode="${key}" class="${mode===key?'active':''}" ${working?'disabled':''} aria-pressed="${mode===key}"><span>${i+1}</span>${label}</button>`).join('')}</nav><div class="stage-action" id="stageAction">${stageActionHTML(p,mode)}</div>${mode==='text'?'<div class="text-review-layout">':''}${mode!=='audio'?`<div class="panel image-panel">${mode==='image'?perspectiveHTML(p):''}${mode==='text'&&!rectified(p)?'<p class="notice warning">本页图片尚未确认。请先返回图片校正。</p>':''}${mode==='text'&&regionMode?regionTaskHTML(p):''}<div class="canvas-wrap" id="canvasWrap" style="touch-action:${mode==='text'&&!regionMode?'pan-y pinch-zoom':'none'}"><canvas id="pageCanvas" aria-label="页面图像、四角与句子定位框"></canvas><span class="canvas-caption">${perspective?.pageId===p.id?'拖动四角，使边框贴合书页':regionMode?'拖动画框，完成后点击「结束画框」':mode==='text'?'点击文字框，对照下方句子':'检查书页边缘与方向'}</span></div>${mode==='image'?imageToolsHTML(p):''}</div>`:''}${mode==='text'?`<div class="text-review-sentences"><div class="section-title"><h3>双语与点读位置 <span class="hint" id="sentenceReviewCount">${p.sentences.filter(s=>sentenceReady(s,p)).length} / ${p.sentences.length} 句已审核</span></h3><button data-act="addSentence" ${working||!rectified(p)?'disabled':''}>＋ 添加句子</button></div>${p.analysisWarnings?.length?`<div class="notice warning">分析提示：${p.analysisWarnings.map(escape).join('；')}</div>`:''}${p.sentences.map((s,i)=>sentenceHTML(s,i,p)).join('')||'<div class="empty compact-empty">还没有文案。先分析本页，或手动添加句子。<br>纯插画页可直接人工确认无需文案。<br><button data-act="reviewPage" '+(working||!rectified(p)?'disabled':'')+'>确认本页无需文案</button></div>'}${textToolsHTML(p)}</div></div>`:mode==='audio'?audioHTML(p):''}${mode!=='audio'?`<div class="provider-strip"><span>${escape(providerLabel())}</span><button class="plain small" data-act="providerConfig" ${working?'disabled':''}>模型与凭据设置</button><span class="hint">AI 分析会发送图片到你配置的服务；人工编辑与本地配音无需上传。</span></div>`:''}`:'<div class="empty"><h2>从一张照片开始</h2><p>导入后依次完成图片校正、文字审核和本地配音。</p><button class="primary" data-act="import">选择 JPEG / PNG</button><button data-act="sample">使用示例图片</button></div>'}</section></div>`
}
function sentenceHTML(s,i,p){
 const ready=sentenceReady(s,p),regions=s.regions||[],selected=s.id===selectedSentenceId,disabled=working||!rectified(p)?'disabled':'';
 return `<article class="sentence-row ${selected?'selected':''}" data-sentence="${s.id}"><div class="sentence-top"><button class="plain sentence-select" data-sact="select" data-sid="${s.id}" ${working?'disabled':''} aria-pressed="${selected}">${sentenceLabelHTML(s,i,p)}</button><details class="tool-disclosure compact"><summary aria-label="句子 ${i+1} 的更多操作">更多</summary><div class="tool-content"><button data-sact="up" data-sid="${s.id}" ${i===0||working?'disabled':''}>上移</button><button data-sact="down" data-sid="${s.id}" ${i===p.sentences.length-1||working?'disabled':''}>下移</button><button data-sact="split" data-sid="${s.id}" ${working?'disabled':''}>拆句</button><button class="danger" data-sact="delete" data-sid="${s.id}" ${working?'disabled':''}>删除</button></div></details></div><div class="sentence-inputs"><label class="field">英文<textarea data-en="${s.id}" ${disabled}>${escape(s.en)}</textarea></label><label class="field">中文翻译<textarea data-zh="${s.id}" ${disabled}>${escape(s.zh)}</textarea></label></div><div class="sentence-locator"><span class="hint">${regions.length?`${regions.length} 个文字框 · ${s.anchorRevision===(p.imageRevision||0)?'基于当前校正图':'图片已变更，需重新定位'}`:'尚无文字框，需在图片上定位'}</span><button data-sact="anchor" data-sid="${s.id}" ${disabled}>${regions.length?'＋ 添加文字框':'添加点读位置'}</button>${regions.length?`<button data-sact="editRegions" data-sid="${s.id}" ${disabled}>修改已有框</button>`:''}<button class="contextual-review" data-sact="review" data-sid="${s.id}" ${disabled}>${returnToAudioSentenceId===s.id?'确认并返回本句配音':ready?'重新确认本句':'确认本句文字与定位'}</button></div><details class="sentence-detail" data-region-details="${s.id}"><summary>朗读设置与精确坐标</summary><div class="sentence-options"><label>文字类型 <select data-kind="${s.id}" ${disabled}>${[['narration','正文'],['speech','对白'],['label','标签 / 装饰文字']].map(([k,l])=>`<option value="${k}" ${s.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label><input type="checkbox" data-narrate="${s.id}" ${s.includeInNarration!==false?'checked':''} ${disabled}> 加入连续旁白</label></div><div class="region-editor">${regions.map((r,j)=>`<div class="region-item"><span>区域 ${j+1}</span>${[['x','左'],['y','上'],['w','宽'],['h','高']].map(([k,l])=>`<label>${l}%<input type="number" min="0" max="100" step="0.1" data-region-sid="${s.id}" data-region-index="${j}" data-region-axis="${k}" value="${(r[k]*100).toFixed(1)}" ${disabled}></label>`).join('')}<button class="plain danger" data-remove-region="${s.id}" data-region-index="${j}" ${disabled}>删除框</button></div>`).join('')||'<span class="hint">在图片上画框后，可在这里微调坐标。</span>'}</div></details></article>`
}
function audioHTML(p){return `<div class="audio-overview"><h3>本页英文配音</h3><p class="hint">按句子顺序生成；首次使用需下载本地语音模型，请保持页面在前台。</p>${p.sentences.map((s,i)=>{const valid=s.audio&&s.audioText===s.en&&sentenceReady(s,p);return `<article class="audio-row" data-audio-sentence="${s.id}" aria-busy="${ttsActivity?.sentenceId===s.id&&ttsActivity.status==='working'}"><div class="audio-copy"><span class="hint">句子 ${i+1} · ${s.includeInNarration===false?'不加入旁白':valid?'音频已就绪':'待配音'}</span><p>${escape(s.en)}</p><small>${escape(s.zh)}</small><div class="sentence-job" data-tts-status="${s.id}" data-state="${ttsActivity?.sentenceId===s.id?ttsActivity.status:''}" role="status" ${ttsActivity?.sentenceId===s.id?'':'hidden'}>${ttsActivity?.sentenceId===s.id?escape(ttsActivity.text):''}</div></div><div class="sentence-audio">${valid?`<audio controls preload="none" src="${url(s.audio)}"></audio>`:''}<button data-sact="tts" data-sid="${s.id}" ${working||!sentenceReady(s,p)||s.includeInNarration===false?'disabled':''}>${ttsActivity?.sentenceId===s.id&&ttsActivity.status==='working'?'正在处理…':s.audio?'重新配音':'生成配音'}</button><details class="tool-disclosure compact"><summary aria-label="句子 ${i+1} 的更多配音操作">更多</summary><div class="tool-content"><button data-sact="edit" data-sid="${s.id}" ${working?'disabled':''}>返回文字编辑</button>${s.audio?`<a href="${url(s.audio)}" download="sentence-${i+1}.wav">下载 WAV${valid?'':'（旧版）'}</a>`:''}</div></details></div></article>`}).join('')||'<div class="empty compact-empty">本页没有旁白，无需生成配音。</div>'}</div><details class="tool-disclosure"><summary>整本配音</summary><div class="tool-content"><p class="hint">仅处理已审核页面中缺少最新音频的句子，可在本句结束后暂停。</p><button data-act="batchTTS" ${working?'disabled':''}>生成整本待配音</button></div></details>`}

function bindStructuredInputs(){document.querySelectorAll('[data-region-sid]').forEach(el=>el.oninput=()=>{const p=currentPage(),s=p.sentences.find(s=>s.id===el.dataset.regionSid);const value=Number(el.value);if(!Number.isFinite(value)||value<0||value>100)return;s.regions[Number(el.dataset.regionIndex)][el.dataset.regionAxis]=value/100;s.anchorRevision=p.imageRevision||0;invalidateSentence(s,p);saveSoon();drawCanvas(false)});document.querySelectorAll('[data-kind],[data-narrate]').forEach(el=>el.onchange=()=>{const p=currentPage(),s=p.sentences.find(s=>s.id===(el.dataset.kind||el.dataset.narrate));if(el.dataset.kind)s.kind=el.value;else s.includeInNarration=el.checked;invalidateSentence(s,p);saveSoon()});document.querySelectorAll('[data-remove-region]').forEach(el=>el.onclick=async()=>{if(working)return;const p=currentPage(),s=p.sentences.find(s=>s.id===el.dataset.removeRegion);s.regions.splice(Number(el.dataset.regionIndex),1);invalidateSentence(s,p);await persist();render()})}
async function reviewSentence(p,s){if(working)return toast('请等待当前处理结束');if(!rectified(p))return toast('请先确认当前图像端正可用');if(!s.en.trim()||!s.zh.trim()||!validRegions(s))return toast('请补齐英文、中文与有效文字框，再确认');s.reviewed=true;s.anchorRevision=p.imageRevision||0;job='';const returnToAudio=returnToAudioSentenceId===s.id;if(returnToAudio){editorMode='audio';returnToAudioSentenceId=null}await persist();render();if(returnToAudio)revealAudioSentence(s.id);toast('已人工确认本句文字与定位')}
async function reviewPage(){const p=currentPage();if(working)return;if(!rectified(p))return toast('请先确认校正图');const invalid=p.sentences.filter(s=>!s.en.trim()||!s.zh.trim()||!validRegions(s));if(invalid.length)return toast(`${invalid.length} 句缺少双语或有效文字框，请先补齐`);return confirmAction('确认已逐项检查本页？','请确认正文、翻译、句子顺序、每个文字框及是否加入旁白均已核对。纯插画页会标记为无需文案。',async()=>{p.sentences.forEach(s=>{s.reviewed=true;s.anchorRevision=p.imageRevision||0});p.analysisReviewed=true;p.analysisRevision=p.imageRevision||0;editorMode='audio';job='';await persist();render()},'整页人工确认')}
function providerLabel(){return providerState.configured?(providerState.unlocked?(providerState.hasToken===false?'○ 服务地址已配置 · 待填写 Token':'● 多模态服务已配置 · 已解锁'):'○ 多模态服务已配置 · 待解锁'):providerState.error?'○ 配置暂不可用':'○ 多模态服务尚未配置'}
async function checkProvider(){try{const state=credentials.getStatus(),config=credentials.getConfig();providerState={...state,configured:state.configured&&!!config.baseURL&&!!config.model,model:config.model,hasToken:state.unlocked?!!credentials.getCredentials().apiToken:null,checked:true}}catch(e){providerState={configured:false,unlocked:false,checked:true,error:e.message}}const status=$('.provider-strip>span');if(status)status.textContent=providerLabel();const nav=$('#credentialsState');if(nav){const state=credentials.getStatus();nav.textContent=state.corrupt?'配置损坏':state.configured?(state.unlocked?'已解锁':'待解锁'):'未配置'}return providerState}

function settingsStateText(){const s=credentials.getStatus();return s.corrupt?'配置文件无法读取：'+(s.error||'记录损坏')+' 请保留原数据后再清空重建。':s.configured?(s.unlocked?'凭据已解锁 · 当前标签页刷新无需再次输入密码':'凭据已加密保存 · 输入密码解锁'):'尚未保存凭据 · 设置密码后保存'}
async function providerConfig(){
 await checkProvider();const state=credentials.getStatus();let c={};try{c=credentials.getConfig()||{}}catch{}const locked=state.configured&&!state.unlocked;
 const field=(id,label,value='',extra='')=>`<label class="field">${label}<input id="${id}" value="${escape(value)}" ${extra}></label>`;
 const secret=(id,label)=>`<label class="field">${label}<input id="${id}" type="password" autocomplete="new-password" autocapitalize="none" spellcheck="false" placeholder="${state.configured?'留空保留已保存值':'尚未填写'}" ${locked?'disabled':''}></label>`;
 showModal(`<div class="eyebrow">YOUR CONNECTIONS</div><h2>模型与凭据设置</h2><p id="credentialsStatus" class="notice">${escape(settingsStateText())}</p><p class="hint">图片会由浏览器直接发送到你配置的多模态服务，服务须允许跨域请求（CORS）。保存配置不会调用模型。COS 仅保存设置，暂不接线。</p><form id="credentialsForm"><fieldset id="connectionFields" ${locked||state.corrupt?'disabled':''}><h3>多模态 AI</h3><div class="settings-grid">${field('modelBaseURL','OpenAI 兼容 Base URL',c.baseURL,'type="url" inputmode="url" autocomplete="url" placeholder="https://api.example.com/v1" autocapitalize="none" spellcheck="false"')}${field('modelName','模型名称',c.model,'autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="支持图片的模型名称"')}<label class="field">结构化 JSON 模式<select id="modelJsonMode"><option value="on" ${c.jsonMode!=='off'?'selected':''}>开启（服务支持时使用）</option><option value="off" ${c.jsonMode==='off'?'selected':''}>关闭（兼容不支持的服务）</option></select></label>${secret('modelToken','API Token')}</div><h3>COS 设置 <span class="hint">仅保存，尚未连接</span></h3><div class="settings-grid">${field('cosBucket','Bucket',c.cosBucket,'autocomplete="off" autocapitalize="none" spellcheck="false"')}${field('cosRegion','Region',c.cosRegion,'autocomplete="off" autocapitalize="none" spellcheck="false"')}${field('cosPrefix','对象前缀',c.cosPrefix,'autocomplete="off" autocapitalize="none" spellcheck="false"')}${secret('cosSecretId','SecretId')}${secret('cosSecretKey','SecretKey')}</div></fieldset>${!state.configured?`<div class="settings-grid">${secret('vaultPassword','设置解锁密码（请牢记）')}${secret('vaultPasswordAgain','再次输入密码')}</div>`:locked?`<label class="field">解锁密码<input id="vaultUnlockPassword" type="password" autocomplete="current-password"></label>`:''}<p class="hint">敏感配置通过密码加密后保存在本机 localStorage，密码保存在当前标签页 sessionStorage。浏览器恢复会话时可能仍保持解锁；离开时可手动锁定。绘本备份不包含这些设置。</p><div class="settings-text-tools"><button type="button" id="exportConfigurationText">导出配置文本</button><button type="button" id="importConfigurationText" ${working?'disabled':''}>解析配置文本</button></div><p id="settingsError" class="settings-error" role="alert"></p><div class="modal-actions settings-actions"><button type="button" data-close>关闭</button>${state.configured?`<button type="button" id="clearCredentials" class="danger" ${working?'disabled':''}>清空配置</button>`:''}${state.unlocked?`<button type="button" id="changeVaultPassword" ${working?'disabled':''}>更改密码</button><button type="button" id="lockCredentials">手动锁定</button>`:''}<button type="submit" class="primary" id="saveCredentials" ${working||state.corrupt?'disabled':''}>${locked?'解锁':'加密保存'}</button></div></form>`);
 modal.classList.add('settings-modal');delete $('#modalBody').dataset.invalidated;
 $('#exportConfigurationText').onclick=exportConfigurationText;$('#importConfigurationText').onclick=importConfigurationText;
 let busy=false;
 async function runSettings(fn){if(busy)return;busy=true;settingsBusy=true;const controls=[...$('#modalBody').querySelectorAll('button,input,select')].map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);$('#settingsError').textContent='';try{await fn()}catch(e){if($('#settingsError'))$('#settingsError').textContent=e.message||'操作失败，请重试'}finally{busy=false;settingsBusy=false;controls.forEach(([el,disabled])=>{if(el.isConnected)el.disabled=disabled});const submit=$('#saveCredentials');if(submit)submit.disabled=working||credentials.getStatus().corrupt||$('#modalBody').dataset.invalidated==='true'}}
 $('#credentialsForm').onsubmit=e=>{e.preventDefault();if(working)return;runSettings(async()=>{if(locked){await credentials.unlock($('#vaultUnlockPassword').value);await providerConfig();toast('凭据已解锁');return}const password=$('#vaultPassword')?.value;if(!state.configured&&password!==$('#vaultPasswordAgain').value)throw new Error('两次输入的密码不一致');const config={baseURL:$('#modelBaseURL').value.trim(),model:$('#modelName').value.trim(),jsonMode:$('#modelJsonMode').value,cosBucket:$('#cosBucket').value.trim(),cosRegion:$('#cosRegion').value.trim(),cosPrefix:$('#cosPrefix').value.trim()};const secretUpdates={};for(const [id,key] of [['modelToken','apiToken'],['cosSecretId','cosSecretId'],['cosSecretKey','cosSecretKey']]){const value=$('#'+id).value.trim();if(value)secretUpdates[key]=value}await credentials.save({config,credentials:secretUpdates,...(!state.configured?{password}: {})});await providerConfig();toast('配置已加密保存；尚未发送任何图片')})};
 if($('#lockCredentials'))$('#lockCredentials').onclick=async()=>{try{credentials.lock();await providerConfig();toast('已锁定，当前标签页的解锁密码已清除')}catch(e){if($('#settingsError'))$('#settingsError').textContent=e.message}};
 if($('#changeVaultPassword'))$('#changeVaultPassword').onclick=()=>{showModal(`<h2>更改解锁密码</h2><p class="hint">凭据将使用新密码重新加密，当前标签页保持解锁。</p><form id="passwordChangeForm"><label class="field">新密码<input id="newVaultPassword" type="password" autocomplete="new-password"></label><label class="field">再次输入新密码<input id="newVaultPasswordAgain" type="password" autocomplete="new-password"></label><p id="settingsError" class="settings-error" role="alert"></p><div class="modal-actions"><button type="button" id="passwordBack">返回设置</button><button type="submit" class="primary" id="saveCredentials">重新加密</button></div></form>`);modal.classList.add('settings-modal');$('#passwordBack').onclick=providerConfig;$('#passwordChangeForm').onsubmit=e=>{e.preventDefault();runSettings(async()=>{const p=$('#newVaultPassword').value;if(p!==$('#newVaultPasswordAgain').value)throw new Error('两次输入的密码不一致');await credentials.changePassword(p);await providerConfig();toast('解锁密码已更新')})}};
 if($('#clearCredentials'))$('#clearCredentials').onclick=()=>confirmAction('清空模型与凭据配置？','将删除加密凭据、普通连接配置与当前标签页密码，需要重新填写。绘本、图片、审核结果和音频仍保留。',async()=>{credentials.clear();await checkProvider();toast('连接配置已清空，绘本数据已保留')},'确认清空配置');
}
function settingsTextShell(html){showModal(html);modal.classList.add('settings-modal');delete $('#modalBody').dataset.invalidated}
async function exportConfigurationText(){
 settingsTextShell(`<div class="eyebrow">SAVE OR SHARE</div><h2>导出配置文本</h2><p class="hint">导出当前已保存的配置，不包含尚未保存的输入。普通配置适合分享；加密完整配置适合自己备份。</p><label class="field">导出内容<select id="configurationExportKind"><option value="public">普通配置（不含 Token 或 COS 密钥）</option><option value="encrypted">含凭据的加密配置（需要原解锁密码）</option></select></label><p id="configurationTextHint" class="notice"></p><label class="field">配置 JSON<textarea id="configurationText" class="configuration-text" rows="10" readonly spellcheck="false" autocomplete="off" aria-label="导出的配置文本"></textarea></label><p id="settingsError" class="settings-error" role="alert"></p><div class="modal-actions settings-actions"><button type="button" data-close>关闭</button><button type="button" id="configurationBack">返回设置</button><button type="button" class="primary" id="copyConfigurationText">复制文本</button></div>`);
 const update=()=>{try{const encrypted=$('#configurationExportKind').value==='encrypted';$('#configurationText').value=credentials.exportText({includeCredentials:encrypted});$('#configurationTextHint').textContent=encrypted?'包含加密凭据，不包含密码。恢复时须输入导出时使用的解锁密码；请妥善保存。':'仅包含模型地址、模型名称、JSON 模式与 COS 普通配置，不包含 Token、密钥或密码。';$('#settingsError').textContent='';$('#copyConfigurationText').disabled=false}catch(e){$('#configurationText').value='';$('#settingsError').textContent=e.message||'无法导出配置';$('#copyConfigurationText').disabled=true}};
 $('#configurationExportKind').onchange=update;$('#configurationBack').onclick=()=>providerConfig().catch(fail);update();
 $('#copyConfigurationText').onclick=async()=>{const field=$('#configurationText'),snapshot=field.value;try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText(snapshot);if(field.isConnected)toast('配置文本已复制')}catch{if(field.isConnected){field.focus();field.select();$('#settingsError').textContent='浏览器未允许自动复制，文本已选中，请使用系统复制操作。'}}};
}
function importConfigurationText(){
 settingsTextShell(`<div class="eyebrow">RESTORE CONNECTIONS</div><h2>解析配置文本</h2><p class="hint">粘贴导出的 JSON，先解析预览，再确认应用。此操作不会调用模型或操作 COS，也不会修改绘本。</p><label class="field">配置 JSON<textarea id="configurationText" class="configuration-text" rows="8" spellcheck="false" autocomplete="off" autocapitalize="none" placeholder="粘贴普通配置或加密配置文本"></textarea></label><div class="settings-text-tools"><button type="button" id="parseConfigurationText">解析并预览</button></div><div id="configurationPreview"></div><p id="settingsError" class="settings-error" role="alert"></p><div class="modal-actions settings-actions"><button type="button" data-close>关闭</button><button type="button" id="configurationBack">返回设置</button><button type="button" class="primary" id="saveCredentials" disabled>确认应用配置</button></div>`);
 let parsed=null,snapshot='',busy=false;const container=$('#modalBody'),input=$('#configurationText');
 const error=e=>{if(container=== $('#modalBody')&&input.isConnected)$('#settingsError').textContent=e.message||'配置文本无法解析，请检查格式'};
 const reset=()=>{parsed=null;snapshot='';$('#configurationPreview').innerHTML='';$('#saveCredentials').disabled=true;$('#settingsError').textContent=''};
 input.oninput=reset;$('#configurationBack').onclick=()=>providerConfig().catch(fail);
 $('#parseConfigurationText').onclick=()=>{if(container.dataset.invalidated==='true')return;reset();try{const candidate=input.value;const result=credentials.parseText(candidate),state=credentials.getStatus();parsed=result;snapshot=candidate;const rows=[['模型地址',result.config.baseURL],['模型名称',result.config.model],['JSON 模式',result.config.jsonMode==='off'?'关闭':'开启'],['COS Bucket',result.config.cosBucket],['COS Region',result.config.cosRegion],['COS 前缀',result.config.cosPrefix],['凭据',result.credentialsIncluded?'包含加密凭据':'不包含凭据']];let password='';if(result.type==='encrypted')password='<label class="field">源配置的解锁密码<input id="configurationSourcePassword" type="password" autocomplete="current-password"></label>';else if(!state.configured)password='<div class="settings-grid"><label class="field">设置本机解锁密码<input id="configurationNewPassword" type="password" autocomplete="new-password"></label><label class="field">再次输入密码<input id="configurationNewPasswordAgain" type="password" autocomplete="new-password"></label></div>';else if(!state.unlocked)password='<label class="field">当前配置的解锁密码<input id="configurationCurrentPassword" type="password" autocomplete="current-password"></label>';$('#configurationPreview').innerHTML=`<h3>配置预览</h3><dl class="configuration-preview">${rows.map(([k,v])=>`<dt>${escape(k)}</dt><dd>${escape(v||'未填写')}</dd>`).join('')}</dl><p class="notice">${result.type==='encrypted'?'确认后将替换当前普通配置和整份凭据，并使用源密码解锁。':'确认后将替换当前普通配置，保留本机已保存的 Token 和 COS 密钥。'}</p>${password}${state.corrupt?'<p class="settings-error">本机配置已损坏，请返回设置，明确清空后再导入。</p>':''}<label class="configuration-confirm"><input id="confirmConfigurationImport" type="checkbox">我确认应用上述配置，替换范围如上所示</label>`;$('#saveCredentials').disabled=working||state.corrupt; }catch(e){reset();error(e)}};
 $('#saveCredentials').onclick=async()=>{if(busy||working||!parsed||snapshot!==input.value||container.dataset.invalidated==='true')return;if(!$('#confirmConfigurationImport')?.checked)return error(new Error('请先勾选确认应用配置'));const captured=parsed,text=snapshot,state=credentials.getStatus();let password;if(captured.type==='encrypted')password=$('#configurationSourcePassword').value;else if(!state.configured){password=$('#configurationNewPassword').value;if(password!==$('#configurationNewPasswordAgain').value)return error(new Error('两次输入的密码不一致'))}const currentPassword=$('#configurationCurrentPassword')?.value;
 busy=true;settingsBusy=true;const controls=[...container.querySelectorAll('button,input,select,textarea')].map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);$('#settingsError').textContent='';
 try{if(captured.type==='public'&&state.configured&&!state.unlocked)await credentials.unlock(currentPassword);if(container.dataset.invalidated==='true')throw new Error('配置已在其他标签页变化，请重新打开设置');await credentials.importText(text,{expectedRevision:captured.revisionOpaque,...(password===undefined?{}:{password})});if(input.isConnected){await providerConfig();toast('配置已导入；未调用模型或操作 COS')}}catch(e){error(e)}finally{busy=false;settingsBusy=false;controls.forEach(([el,disabled])=>{if(el.isConnected)el.disabled=disabled});if(input.isConnected&&container.dataset.invalidated==='true')$('#saveCredentials').disabled=true}
 };
}

async function requireProvider(){await checkProvider();if(!providerState.configured||!providerState.unlocked||providerState.hasToken===false){await providerConfig();return null}return getMultimodal()}
async function multimodalCorners(){const target=book,p=currentPage();const mm=await requireProvider();if(!mm)return;if(book!==target||currentPage()!==p)return toast('页面已切换，请重新发起');const image=p.image,rev=p.imageRevision||0;return withImageTask(async()=>{ai.releaseModels();const result=await mm.suggestCorners(image,setJob);if(p.image!==image||(p.imageRevision||0)!==rev)throw new Error('图像已变化，AI 四角结果已丢弃');perspective={pageId:p.id,image,corners:result.corners||[{x:.05,y:.05},{x:.95,y:.05},{x:.95,y:.95},{x:.05,y:.95}],manualFallback:!result.corners,method:result.corners?'多模态 AI 建议':'手动初始框',sourceMethod:!result.corners?'多模态 AI（未找到可靠四角）':null,needsManual:true,warning:[...(result.warnings||[]),'AI 建议尚未应用，请人工检查四角并确认透视裁剪。'].join(' ')}} ,()=>perspective?.manualFallback?'AI 未识别到可靠四角，请手动定位，初始框尚未应用':'AI 四角建议已返回，尚未应用，请检查后确认')}
async function applyAnalysis(p,raw){const structure=await getStructure(),result=structure.validateAnalysis(raw);p.sentences=result.sentences.map(s=>({...s,id:uid('sentence'),reviewed:false,anchorRevision:p.imageRevision||0,audio:null,audioText:''}));p.analysisWarnings=result.warnings||[];p.analysisReviewed=false;p.analysisRevision=p.imageRevision||0;p.analysisReviewed=false;p.textRevision=(p.textRevision||0)+1;selectedSentenceId=p.sentences[0]?.id;editorMode='text';await persist();setJob(`已导入 ${p.sentences.length} 句结构化文案，全部待人工审核${result.warnings?.length?' · '+result.warnings.join('；'):''}`)}
async function analyzePage(){const target=book,p=currentPage();if(!rectified(p))return toast('请先确认校正图');const mm=await requireProvider();if(!mm)return;if(book!==target||currentPage()!==p)return toast('页面已切换，请重新发起');const run=()=>withJob(async()=>{const image=p.image,rev=p.imageRevision||0,textRev=p.textRevision||0;ai.releaseModels();const result=await mm.analyzePage(image,setJob);if(p.image!==image||rev!==(p.imageRevision||0)||textRev!==(p.textRevision||0)){setJob('图片或文案已变化，迟到的 AI 结果未覆盖内容');return}await applyAnalysis(p,result)});if(p.sentences.length)return confirmAction('重新分析并替换本页文案？','将替换当前页的分句、双语、定位与配音。发布版本不受影响，请先确认已保留需要的人工修改。',run,'重新分析');return run()}
async function importAnalysis(){const p=currentPage();if(!rectified(p))return toast('请先确认此图端正可用');showModal(`<h2>导入本页结构化 JSON</h2><p class="hint">这是手动数据导入，不代表 AI 实测。regions 使用当前校正图上 0–1 的归一化坐标，可以为一句设置多个框。</p><textarea id="analysisJSON" rows="10" style="width:100%" placeholder='{"sentences":[{"en":"Hello.","zh":"你好。","regions":[{"x":0.1,"y":0.2,"w":0.3,"h":0.1}],"kind":"narration","includeInNarration":true}]}'></textarea><p class="hint">导入会替换本页现有文案与配音，所有句子重新进入待审核。</p><div class="modal-actions"><button data-close>取消</button><button class="primary" id="importAnalysisConfirm">校验并导入</button></div>`);$('#importAnalysisConfirm').onclick=async()=>{try{if(working)return;if(currentPage()!==p)throw new Error('页面已切换，请重新导入');const raw=JSON.parse($('#analysisJSON').value);await applyAnalysis(p,raw);closeModal();render();toast('结构化数据已校验导入，请逐句审核')}catch(e){fail(e)}}}
async function exportAnalysis(){const p=currentPage(),scanner=await getScanner(),info=await scanner.getImageInfo(p.image);const data={format:'pbook-page-analysis',version:1,bookId:book.id,pageId:p.id,image:{...info,revision:p.imageRevision||0,rectificationReviewed:rectified(p)},coordinateSystem:'normalized 0..1, origin top-left, based on CURRENT RECTIFIED IMAGE; regions={x,y,w,h}',sentences:p.sentences.map((s,i)=>({...s,audio:undefined,order:i+1})),warnings:p.analysisWarnings||[]};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`page-analysis-${p.id}.json`);toast('已准备本页结构化 JSON 下载')}

function bindInputs(){document.querySelectorAll('[data-en],[data-zh]').forEach(el=>el.onfocus=()=>{if(working)return;selectedSentenceId=el.dataset.en||el.dataset.zh;document.querySelectorAll('[data-sentence]').forEach(row=>{const selected=row.dataset.sentence===selectedSentenceId;row.classList.toggle('selected',selected);row.querySelector('[data-sact=select]')?.setAttribute('aria-pressed',String(selected))});drawCanvas(false)});if(working)document.querySelectorAll('#workspace input,#workspace textarea,#workspace select,[data-tab]').forEach(el=>el.disabled=true);bindStructuredInputs();document.querySelectorAll('[data-corner]').forEach(el=>el.oninput=()=>{if(working||!perspective)return;const value=Number(el.value);if(!Number.isFinite(value)||value<0||value>100)return;perspective.corners[Number(el.dataset.corner)][el.dataset.axis]=value/100;drawCanvas(false)});document.querySelectorAll('[data-meta]').forEach(el=>el.oninput=()=>{const k=el.dataset.meta;metadata()[k]=k==='tags'?el.value.split(/[,，]/).map(x=>x.trim()).filter(Boolean):k==='sort'?Number(el.value)||0:el.value;saveSoon()});document.querySelectorAll('[data-en],[data-zh]').forEach(el=>el.oninput=()=>{const p=currentPage(),s=p.sentences.find(s=>s.id===(el.dataset.en||el.dataset.zh));s[el.dataset.en?'en':'zh']=el.value;invalidateSentence(s,p);saveSoon();});document.querySelectorAll('[data-crop]').forEach(el=>el.oninput=()=>{crop[el.dataset.crop]=Number(el.value);drawCanvas(false)})}
function markImageChanged(p){editorMode='image';perspective=null;regionMode=false;p.rectificationReviewed=false;p.analysisReviewed=false;p.sentences.forEach(s=>s.reviewed=false);p.imageRevision=(p.imageRevision||0)+1;p.ocrStale=true;p.ocr=undefined;crop={x:0,y:0,w:100,h:100}}
async function decode(blob){const scanner=await getScanner();return scanner.decodeScaled(blob,4096)}
async function transformed(blob,fn){const img=await decode(blob);const canvas=document.createElement('canvas');const result=fn(canvas,img);await result;img.close();return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('图片处理失败')),'image/jpeg',.94))}
function perspectiveHTML(p){if(perspective?.pageId!==p.id)return '';const labels=['左上','右上','右下','左下'];return `<div class="perspective-panel"><div class="section-title"><h3>${perspective.manualFallback?'未识别到可靠边框 · 请手动定位':'四角透视校正'} <span class="status">尚未应用 · 请复核</span></h3><button class="plain small" data-act="cancelBorder" ${working?'disabled':''}>撤销选区</button></div><p class="hint ${perspective.needsManual?'busy':''}">${escape(perspective.warning||'请检查四角是否准确落在书页边缘，确认后再应用。')}${perspective.method?' · '+escape(perspective.method):''}${perspective.sourceMethod?' · 自动检测来源：'+escape(perspective.sourceMethod):''}</p><details class="corner-details"><summary>精确调整四角坐标</summary><div class="corner-fields">${perspective.corners.map((q,i)=>`<div><b>${labels[i]}</b><label>横向 %<input type="number" min="0" max="100" step="0.1" data-corner="${i}" data-axis="x" ${working?'disabled':''} value="${(q.x*100).toFixed(1)}"></label><label>纵向 %<input type="number" min="0" max="100" step="0.1" data-corner="${i}" data-axis="y" ${working?'disabled':''} value="${(q.y*100).toFixed(1)}"></label></div>`).join('')}</div></details><span class="hint">保留原图；仅校正透视，不展平书脊弯曲。</span></div>`}
async function drawCanvas(load=true){const p=currentPage(),canvas=$('#pageCanvas');if(!p||!canvas)return;if(load){const scanner=await getScanner();const info=await scanner.getImageInfo(p.image);const decoded=await scanner.decodeScaled(p.image,1600);if(currentPage()?.id!==p.id||!canvas.isConnected){decoded.close();return}if(imageCache)imageCache.close();imageCache=decoded;previewInfo=info}const img=imageCache;if(!img)return;const scale=Math.min(1,1100/img.width);canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);const sx=canvas.width/(previewInfo?.width||img.width),sy=canvas.height/(previewInfo?.height||img.height);if(!p.ocrStale&&p.ocr){ctx.lineWidth=2;ctx.font='15px sans-serif';p.ocr.forEach((r,i)=>{if(!r.poly?.length)return;ctx.strokeStyle=r.score<.85?'#c57b39':'#3e9275';ctx.beginPath();r.poly.forEach((q,j)=>j?ctx.lineTo(q[0]*sx,q[1]*sy):ctx.moveTo(q[0]*sx,q[1]*sy));ctx.closePath();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.fillText(String(i+1),r.poly[0][0]*sx,r.poly[0][1]*sy-4)})}const corners=perspective?.pageId===p.id?perspective.corners:null;if(!corners){p.sentences.forEach((s,i)=>(s.regions||[]).forEach(r=>{if(![r.x,r.y,r.w,r.h].every(Number.isFinite))return;const chosen=s.id===selectedSentenceId;ctx.strokeStyle=chosen?'#c2812e':s.reviewed?'#43866a':'#6b87a2';ctx.fillStyle=chosen?'#f6c46b35':'#6d9e8512';ctx.lineWidth=chosen?3:1.5;ctx.setLineDash(s.anchorRevision===(p.imageRevision||0)?[]:[5,4]);ctx.fillRect(r.x*canvas.width,r.y*canvas.height,r.w*canvas.width,r.h*canvas.height);ctx.strokeRect(r.x*canvas.width,r.y*canvas.height,r.w*canvas.width,r.h*canvas.height);ctx.setLineDash([]);ctx.font='bold 13px sans-serif';ctx.fillStyle=ctx.strokeStyle;ctx.fillText(String(i+1),r.x*canvas.width+4,r.y*canvas.height+15)}));if(regionDraft){ctx.strokeStyle='#cc8b35';ctx.lineWidth=3;ctx.strokeRect(regionDraft.x*canvas.width,regionDraft.y*canvas.height,regionDraft.w*canvas.width,regionDraft.h*canvas.height)}}if(corners){ctx.fillStyle='#183f3b55';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#f2bb67';ctx.lineWidth=3;ctx.beginPath();corners.forEach((q,i)=>i?ctx.lineTo(q.x*canvas.width,q.y*canvas.height):ctx.moveTo(q.x*canvas.width,q.y*canvas.height));ctx.closePath();ctx.stroke();corners.forEach((q,i)=>{ctx.beginPath();ctx.arc(q.x*canvas.width,q.y*canvas.height,11,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#a66625';ctx.stroke();ctx.fillStyle='#183f3b';ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(i+1),q.x*canvas.width,q.y*canvas.height)})}else if(crop.x||crop.y||crop.w!==100||crop.h!==100){ctx.fillStyle='#183f3b33';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#edb05f';ctx.lineWidth=3;ctx.strokeRect(crop.x/100*canvas.width,crop.y/100*canvas.height,crop.w/100*canvas.width,crop.h/100*canvas.height)}if(!load)return;let start=null,dragCorner=-1,tapCandidate=null,tapStart=null;const point=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),r}};canvas.onpointerdown=e=>{if(working)return;const q=point(e);if(perspective?.pageId===p.id){let best=40;perspective.corners.forEach((c,i)=>{const d=Math.hypot((c.x-q.x)*q.r.width,(c.y-q.y)*q.r.height);if(d<best){best=d;dragCorner=i}});if(dragCorner<0)return}else{if(!regionMode){const hit=[...p.sentences].reverse().find(s=>(s.regions||[]).some(r=>q.x>=r.x&&q.x<=r.x+r.w&&q.y>=r.y&&q.y<=r.y+r.h));if(workspaceMode(p)==='text'){tapCandidate=hit?.id||null;tapStart={x:e.clientX,y:e.clientY};return}if(hit){selectedSentenceId=hit.id;render();return}}start=q}canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(working)return;if(tapStart&&Math.hypot(e.clientX-tapStart.x,e.clientY-tapStart.y)>10){tapCandidate=null;tapStart=null}const q=point(e);if(dragCorner>=0&&perspective?.pageId===p.id){perspective.corners[dragCorner]={x:q.x,y:q.y};document.querySelectorAll('[data-corner]').forEach(el=>el.value=(perspective.corners[Number(el.dataset.corner)][el.dataset.axis]*100).toFixed(1));drawCanvas(false);return}if(!start)return;if(regionMode){regionDraft={x:Math.min(start.x,q.x),y:Math.min(start.y,q.y),w:Math.abs(start.x-q.x),h:Math.abs(start.y-q.y)};drawCanvas(false);return}crop={x:Math.round(Math.min(start.x,q.x)*100),y:Math.round(Math.min(start.y,q.y)*100),w:Math.round(Math.abs(start.x-q.x)*100),h:Math.round(Math.abs(start.y-q.y)*100)};document.querySelectorAll('[data-crop]').forEach(el=>el.value=crop[el.dataset.crop]);drawCanvas(false)};canvas.onpointerup=async()=>{if(tapCandidate){const id=tapCandidate;tapCandidate=null;tapStart=null;revealSentence(id);return}tapStart=null;if(regionMode&&regionDraft&&start){const s=p.sentences.find(s=>s.id===selectedSentenceId),r=regionDraft;regionDraft=null;if(s&&r.w>.003&&r.h>.003){s.regions ||= [];s.regions.push(r);s.anchorRevision=p.imageRevision||0;invalidateSentence(s,p);await persist();render()}}start=null;dragCorner=-1};canvas.onpointercancel=()=>{start=null;dragCorner=-1;tapCandidate=null;tapStart=null;regionDraft=null;drawCanvas(false)}}
async function detectBorder(){const p=currentPage();if(!p)return;const image=p.image;return withImageTask(async()=>{ai.releaseModels();const scanner=await getScanner();let result;try{result=await scanner.suggestCorners(image)}finally{scanner.releaseScanner()}if(p.image!==image)throw new Error('图片已改变，请重新检测');perspective={...result,manualFallback:!result.corners,method:result.corners?result.method:'手动初始框',sourceMethod:!result.corners?result.method:null,pageId:p.id,image,corners:result.corners||[{x:.05,y:.05},{x:.95,y:.05},{x:.95,y:.95},{x:.05,y:.95}],needsManual:result.needsManual||!result.corners,warning:result.warning||(!result.corners?'没有找到可靠边框，请手动将四角拖到书页边缘。':'候选边框尚未应用，请检查四角后确认。')}} ,()=>perspective?.manualFallback?'未识别到可靠边框，请手动定位四角；初始框尚未应用':'边框检测完成，尚未应用；请检查并调整四角')}
async function applyBorder(){const p=currentPage(),candidate=perspective;if(!p||candidate?.pageId!==p.id)return;if(candidate.image!==p.image)return toast('图片已改变，请重新选择四角');return withImageTask(async()=>{const scanner=await getScanner();let output;try{output=await scanner.rectify(p.image,candidate.corners)}finally{scanner.releaseScanner()}p.original ||= p.image;p.image=output;markImageChanged(p);p.rectificationReviewed=true;p.rectificationRevision=p.imageRevision||0;editorMode='text';await persist()},'已应用透视裁剪，原图与文案已保留，请分析并审核正文')}

async function withImageTask(fn,success='图片处理完成，文案已保留，请按需重新识别'){if(working)return toast('当前正在处理，请稍后再试');const target=book;working=true;imageBusy=true;setJob('正在处理图片，请稍候…');render();try{if(book!==target)throw new Error('绘本已切换，图片操作已取消');await fn();if(book!==target)throw new Error('绘本已切换，图片操作已取消');setJob(typeof success==='function'?success():success)}finally{working=false;imageBusy=false;render()}}
async function acceptImages(files,mode='add'){return withImageTask(()=>acceptImagesRaw(files,mode))}
async function acceptImagesRaw(files,mode='add'){const valid=[...files].filter(f=>/image\/(jpeg|png)/.test(f.type));if(valid.length!==files.length)toast('已跳过不支持的格式，请使用 JPEG 或 PNG');for(const f of valid){const im=await decode(f);im.close();if(mode==='cover'){metadata().cover=f;break}if(mode==='replace'){const p=currentPage();p.original=f;p.image=f;markImageChanged(p);break}const p={id:uid('page'),image:f,original:f,sentences:[],imageRevision:0,textRevision:0};book.draft.pages.push(p);pageId=p.id;editorMode='auto';if(!metadata().cover)metadata().cover=f}await persist();render()}
async function pageAction(action){if(action==='fineRotate'){const angle=Number($('#fineAngle').value);if(!Number.isFinite(angle)||angle < -15||angle > 15)return toast('纠偏角度应在 -15° 到 15° 之间');if(angle===0)return toast('0° 无需调整');return withImageTask(()=>pageActionInner(action,true,angle))}if(['rotate','crop','resetImage'].includes(action))return withImageTask(()=>pageActionInner(action,true));return pageActionInner(action,false)}
async function pageActionInner(action,imageLocked,angle=0){const target=book,p=currentPage(),pages=book.draft.pages,i=pages.indexOf(p);if(!p)return;if(working&&!imageLocked)return toast('当前正在处理，请完成或暂停后再调整页面');if(action==='pageUp'||action==='pageDown'){const j=i+(action==='pageUp'?-1:1);if(j<0||j>=pages.length)return;[pages[i],pages[j]]=[pages[j],pages[i]]}if(action==='setCover'){metadata().cover=p.image;toast('已设为草稿封面')}if(action==='rotate'){p.original ||= p.image;p.image=await transformed(p.image,(c,img)=>{c.width=img.height;c.height=img.width;const ctx=c.getContext('2d');ctx.translate(c.width,0);ctx.rotate(Math.PI/2);ctx.drawImage(img,0,0)});markImageChanged(p)}if(action==='fineRotate'){p.original ||= p.image;p.image=await transformed(p.image,(c,img)=>{const rad=angle*Math.PI/180,cos=Math.abs(Math.cos(rad)),sin=Math.abs(Math.sin(rad)),rawWidth=img.width*cos+img.height*sin,rawHeight=img.width*sin+img.height*cos,resize=Math.min(1,4096/Math.max(rawWidth,rawHeight));c.width=Math.ceil(rawWidth*resize);c.height=Math.ceil(rawHeight*resize);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.translate(c.width/2,c.height/2);ctx.rotate(rad);ctx.scale(resize,resize);ctx.drawImage(img,-img.width/2,-img.height/2)});markImageChanged(p)}if(action==='crop'){p.original ||= p.image;const {x,y,w,h}=crop;if(w<1||h<1||x<0||y<0||x+w>100||y+h>100)return toast('裁剪范围需在图片内，宽高至少为 1%');p.image=await transformed(p.image,(c,img)=>{c.width=Math.max(1,Math.round(img.width*w/100));c.height=Math.max(1,Math.round(img.height*h/100));c.getContext('2d').drawImage(img,img.width*x/100,img.height*y/100,img.width*w/100,img.height*h/100,0,0,c.width,c.height)});markImageChanged(p)}if(action==='resetImage'){p.image=p.original;markImageChanged(p)}if(action==='splitPage'){return confirmAction('拆分为左右两个画面？','原画面的文案保留在左页，请手动调整到相应页面。左右页面都会保留当前整幅图片作为恢复原图。',async()=>{if(book!==target)throw new Error('绘本已切换，请重新操作');return withImageTask(async()=>{const original=p.image;const part=side=>transformed(original,(c,img)=>{const half=Math.floor(img.width/2);c.width=side?img.width-half:half;c.height=img.height;c.getContext('2d').drawImage(img,side?half:0,0,c.width,c.height,0,0,c.width,c.height)});const left=await part(0),right=await part(1);p.original=original;p.image=left;markImageChanged(p);pages.splice(i+1,0,{id:uid('page'),image:right,original,sentences:[],imageRevision:0,textRevision:0});await persist();render()})},'拆分页面')}if(action==='mergePage'){const next=pages[i+1];if(!next)return;return confirmAction('合并两个阅读画面？','将当前页与下一页实际拼成一张左右图，文案按原顺序合并。',async()=>{if(book!==target)throw new Error('绘本已切换，请重新操作');return withImageTask(async()=>{const a=await decode(p.image),b=await decode(next.image),c=document.createElement('canvas');const rawHeight=Math.max(a.height,b.height),rawWidth=a.width*rawHeight/a.height+b.width*rawHeight/b.height,factor=Math.min(1,4096/Math.max(rawWidth,rawHeight)),height=Math.round(rawHeight*factor);c.height=height;c.width=Math.round(rawWidth*factor);const ctx=c.getContext('2d'),aw=a.width*height/a.height;ctx.drawImage(a,0,0,aw,height);ctx.drawImage(b,aw,0,c.width-aw,height);const blob=await new Promise(res=>c.toBlob(res,'image/jpeg',.94));a.close();b.close();p.original=blob;p.image=blob;p.sentences.push(...next.sentences);markImageChanged(p);pages.splice(i+1,1);await persist();render()})},'合并页面')}if(action==='deletePage')return confirmAction('删除这个阅读画面？','该页的文案与音频也会从修改草稿中删除，已发布版本不受影响。',async()=>{pages.splice(i,1);pageId=pages[Math.min(i,pages.length-1)]?.id;await persist();render()},'删除页面');await persist();render()}
async function runOCR(p){const image=p.image,rev=p.imageRevision||0,textRev=p.textRevision||0;setJob(`正在识别第 ${book.draft.pages.indexOf(p)+1} 页…`);const result=await ai.recognize(image,setJob);if(p.image!==image||rev!==(p.imageRevision||0)||textRev!==(p.textRevision||0)){setJob('图片或文案已改变，迟到的识别结果未覆盖内容');return}p.ocr=result.items;p.ocrStale=false;p.ocrElapsedMs=result.elapsedMs;p.sentences=result.items.filter(x=>x.text.trim()).map(x=>({id:uid('sentence'),en:x.text,zh:'',regions:[],kind:'narration',includeInNarration:true,reviewed:false,anchorRevision:p.imageRevision||0,audio:null,audioText:''}));p.analysisReviewed=false;p.textRevision=(p.textRevision||0)+1;await persist();setJob(`识别完成 · ${result.items.length} 行 · 请校对文字和朗读顺序`)}
async function withJob(fn){if(working)return;working=true;pause=false;render();try{await fn()}catch(e){setJob(`处理失败：${e.message}。已完成内容已保留，可以重试。`);fail(e)}finally{working=false;await persist().catch(fail);render()}}
async function ocrAction(batch){const p=currentPage();if(batch){const pending=book.draft.pages.filter(p=>!p.ocr&&!p.sentences.length);if(!pending.length)return toast('没有未识别空白页。需要重识别时请在对应页操作。');return withJob(async()=>{for(const page of pending){pageId=page.id;await runOCR(page);if(pause){setJob('已暂停，已完成页面已保存');break}}})}if(!p)return;const run=()=>withJob(()=>runOCR(p));if(p.sentences.length)return confirmAction('重新识别并替换本页文案？','这会替换本页的英文、中文和配音。请先导出备份；其他页面与发布版本不受影响。',run,'重新识别');return run()}
async function runTTS(s){const p=book.draft.pages.find(p=>p.sentences.includes(s));if(s.includeInNarration===false||!sentenceReady(s,p))throw new Error('请先确认校正图、双语文字与定位，再生成配音');const text=s.en.trim();if(!text)return;ttsActivity={sentenceId:s.id,status:'working',text:''};setJob(`正在配音：${text.slice(0,52)}…`);try{const blob=await ai.synthesize(text,setJob);if(s.en.trim()!==text||!sentenceReady(s,p)){ttsActivity.status='warning';ttsActivity.text='文字已变化，本次音频未覆盖，请重新审核后配音';setJob(ttsActivity.text);return}s.audio=blob;s.audioText=s.en;await persist();setJob('配音完成，音频已保存到当前浏览器');ttsActivity.status='complete';ttsActivity.text='✓ 配音已更新，可以试听'}catch(error){ttsActivity.status='error';ttsActivity.text=`配音未完成：${error.message||'请重试'}`;throw error}finally{refreshTTSFeedback()}}

async function ttsAction(s){return withJob(()=>runTTS(s))}
async function batchTTS(){const pending=book.draft.pages.filter(pageReviewed).flatMap(p=>p.sentences.filter(s=>s.includeInNarration!==false&&sentenceReady(s,p))).filter(s=>!s.audio||s.audioText!==s.en);if(!pending.length)return toast('暂无需要配音的已审核句子，请先完成页面校正、双语与定位审核');return withJob(async()=>{for(let i=0;i<pending.length;i++){setJob(`连续配音 ${i+1} / ${pending.length}`);await runTTS(pending[i]);if(pause){setJob('已暂停，已完成音频已保存');break}}})}
function revealSentence(id,{focus=false,regions=false}={}){selectedSentenceId=id;const row=document.querySelector(`[data-sentence="${id}"]`);if(!row)return;document.querySelectorAll('[data-sentence]').forEach(item=>{const selected=item.dataset.sentence===id;item.classList.toggle('selected',selected);item.querySelector('[data-sact=select]')?.setAttribute('aria-pressed',String(selected))});let target=row;if(regions){const details=row.querySelector('[data-region-details]');if(details){details.open=true;target=details}}target.scrollIntoView({block:'center',behavior:focus?'auto':editorScrollBehavior()});if(focus)(regions?row.querySelector('[data-region-sid]'):row.querySelector('[data-en]'))?.focus({preventScroll:true});drawCanvas(false)}
function revealAudioSentence(id){const row=document.querySelector(`[data-audio-sentence="${id}"]`);row?.scrollIntoView({block:'center',behavior:editorScrollBehavior()});row?.querySelector('[data-sact=tts]')?.focus({preventScroll:true})}
function setWorkspace(mode){if(working)return toast('请等待当前处理完成');if(perspective&&mode!=='image')return toast('请先应用四角选区，或撤销选区');editorMode=mode;regionMode=false;regionDraft=null;render();document.querySelector(`[data-mode="${mode}"]`)?.focus({preventScroll:true})}
async function nextPendingPage(){if(working)return;await flush();const next=book.draft.pages.find(p=>p.id!==pageId&&pageStage(p)!==4);if(!next)return actions.previewDraft();pageId=next.id;editorMode='auto';selectedSentenceId=null;regionMode=false;perspective=null;crop={x:0,y:0,w:100,h:100};job='';render()}
async function pageTTS(){const p=currentPage();if(!pageReviewed(p))return toast('请先完成本页人工审核');const pending=pendingAudio(p);if(!pending.length)return toast('本页配音已完成');return withJob(async()=>{for(const s of pending){await runTTS(s);if(pause){setJob('已暂停，已完成音频已保存');break}}})}
async function sentenceAction(action,id){const p=currentPage(),s=p.sentences.find(s=>s.id===id),i=p.sentences.indexOf(s);if(!s)return;if(action==='edit'){editorMode='text';selectedSentenceId=s.id;returnToAudioSentenceId=s.id;render();revealSentence(s.id,{focus:true});return}if(action==='editRegions'){if(working)return;regionMode=false;selectedSentenceId=s.id;render();revealSentence(s.id,{focus:true,regions:true});return}if(action==='select'){selectedSentenceId=s.id;render();return}if(action==='anchor'){if(working)return;editorMode='text';selectedSentenceId=s.id;regionMode=true;perspective=null;render();$('#canvasWrap')?.scrollIntoView({block:'center',behavior:editorScrollBehavior()});return}if(action==='review'){await reviewSentence(p,s);return}if(action==='tts')return ttsAction(s);if(working)return toast('配音期间请先暂停再调整句子');if(action==='up'||action==='down'){const j=i+(action==='up'?-1:1);if(j<0||j>=p.sentences.length)return;[p.sentences[i],p.sentences[j]]=[p.sentences[j],p.sentences[i]];p.sentences.forEach(sentence=>sentence.reviewed=false)}if(action==='delete')p.sentences.splice(i,1);if(action==='split'){showModal(`<h2>拆分句子</h2><p class="hint">每行一句。拆分后需要重新配音；中文请按新分句补充。</p><textarea id="splitText" rows="6" style="width:100%">${escape(s.en)}</textarea><div class="modal-actions"><button data-close>取消</button><button class="primary" id="splitConfirm">确认拆分</button></div>`);$('#splitConfirm').onclick=async()=>{const texts=$('#splitText').value.split('\n').map(x=>x.trim()).filter(Boolean);if(texts.length<2)return toast('请至少输入两行英文');p.sentences.splice(i,1,...texts.map(en=>({id:uid('sentence'),en,zh:'',regions:[],kind:s.kind||'narration',includeInNarration:s.includeInNarration!==false,reviewed:false,anchorRevision:p.imageRevision||0,audio:null,audioText:''})));p.analysisReviewed=false;p.textRevision=(p.textRevision||0)+1;closeModal();await persist();render()};return}p.analysisReviewed=false;p.textRevision=(p.textRevision||0)+1;await persist();render()}
function previewHTML(){const snap=previewSource==='published'?book.published:book.draft;if(!snap)return '<div class="empty">还没有发布版本</div>';const pages=snap.pages, p=pages[readerPage];return `<h2>${escape(snap.metadata.title)}</h2><div class="page-tools"><button class="${previewSource==='draft'?'primary':''}" data-source="draft">修改草稿</button><button class="${previewSource==='published'?'primary':''}" data-source="published" ${book.published?'':'disabled'}>当前发布版本</button><span class="hint">${previewSource==='draft'?'正在预览尚未发布的修改':'独立快照，编辑草稿不会改变这里'}</span></div>${p?`<div class="reader"><div class="reader-stage"><img class="reader-image" src="${url(p.image)}" alt="第 ${readerPage+1} 页">${p.sentences.flatMap((s,i)=>(s.anchorRevision===(p.imageRevision||0)&&validRegions(s)?s.regions:[]).map(r=>`<button class="reader-hotspot ${i===readerSentence?'active':''}" data-reader-sentence="${i}" aria-label="点读：${escape(s.en)}" style="left:${r.x*100}%;top:${r.y*100}%;width:${r.w*100}%;height:${r.h*100}%"></button>`)).join('')}</div><div class="subtitle" id="readerEn">${escape(p.sentences[readerSentence]?.en||'')}</div><div class="subtitle-zh" id="readerZh">${escape(p.sentences[readerSentence]?.zh||'')}</div><div id="readerAudio"></div><div class="reader-controls"><button data-act="readerPrev" ${readerPage===0?'disabled':''}>上一页</button><button class="primary" data-act="readerPlay">▶ 连续播放</button><button data-act="readerStop">暂停</button><button data-act="readerNext" ${readerPage===pages.length-1?'disabled':''}>下一页</button><span class="hint">${readerPage+1} / ${pages.length} 页 · ${p.sentences.length} 句</span></div><p class="hint" id="readerHint">无音频或已过期的句子不会自动朗读，可继续翻页查看。</p></div>`:'<div class="empty">先添加一些阅读画面，再来预览故事。</div>'}`}
function stopReader(){readerPlaying=false;if(readerAudio){readerAudio.pause();readerAudio.onended=null;readerAudio=null}}
function bindReader(){const image=$('.reader-image'),stage=$('.reader-stage'),reader=$('.reader');if(image&&stage&&reader){updateReaderSize=()=>{if(!image.naturalWidth)return;const css=getComputedStyle(reader),available=reader.clientWidth-parseFloat(css.paddingLeft)-parseFloat(css.paddingRight);stage.style.width=Math.max(1,Math.min(available,image.naturalWidth,innerHeight*.55*image.naturalWidth/image.naturalHeight))+'px'};image.onload=updateReaderSize;if(image.complete)updateReaderSize();readerResizeObserver=new ResizeObserver(()=>updateReaderSize?.());readerResizeObserver.observe(reader)}document.querySelectorAll('[data-reader-sentence]').forEach(el=>el.onclick=async()=>{readerSentence=Number(el.dataset.readerSentence);render();if(readerAudio)try{await readerAudio.play()}catch(e){toast('请点击音频控件开始试听')}else toast('此句尚无最新音频')});const snap=previewSource==='published'?book.published:book.draft,p=snap?.pages[readerPage],s=p?.sentences[readerSentence];if(s?.audio&&s.audioText===s.en&&(previewSource==='published'||sentenceReady(s,p))){const a=document.createElement('audio');a.controls=true;a.src=url(s.audio);a.style.marginTop='12px';$('#readerAudio').append(a);readerAudio=a}}
function skipIllustrationPages(snap){while(readerPage<snap.pages.length){const sentences=snap.pages[readerPage].sentences;while(readerSentence<sentences.length&&sentences[readerSentence].includeInNarration===false)readerSentence++;if(readerSentence<sentences.length)return true;readerPage++;readerSentence=0}return false}
async function playReader(){const snap=previewSource==='published'?book.published:book.draft;if(!skipIllustrationPages(snap)){readerPage=Math.max(0,snap.pages.length-1);readerSentence=0;render();toast('已到故事结尾');return}let p=snap.pages[readerPage],s=p?.sentences[readerSentence];if(!s?.audio||s.audioText!==s.en||(previewSource!=='published'&&!sentenceReady(s,p))){toast('当前句子尚未完成审核或缺少最新配音，请先完成审核与配音');return}if(!readerAudio||readerAudio.src!==url(s.audio)){render()}if(!readerAudio){toast('当前句子未完成审核或没有可用音频');return}readerPlaying=true;readerAudio.onended=()=>{if(!readerPlaying)return;readerSentence++;if(readerSentence>=p.sentences.length){readerPage++;readerSentence=0}if(!skipIllustrationPages(snap)){readerPage=snap.pages.length-1;readerSentence=0;render();toast('本次预览播放结束');return}render();playReader()};try{await readerAudio.play()}catch(e){stopReader();toast('请点击音频播放控件开始试听')}}
async function publish(){if(working)return toast('请先完成或暂停 AI 处理');await flush();const errors=store.validateBook(book),pages=book.draft.pages,sentences=pages.flatMap(p=>p.sentences),missing=sentences.filter(s=>s.includeInNarration!==false&&s.en.trim()&&(!s.audio||s.audioText!==s.en)).length,untranslated=sentences.filter(s=>s.en.trim()&&!s.zh.trim()).length;showModal(`<div class="eyebrow">READY FOR YOUR LOCAL SHELF</div><h2>${book.published?'发布本次修改':'把故事放上书架'}</h2><p class="muted">发布到当前浏览器的本地书库。线上网站与 COS 不会发生变化。</p><ul class="checklist">${errors.length?errors.slice(0,20).map(x=>`<li>✕ ${escape(x)}</li>`).join(''):'<li>✓ 书名、封面与页面已准备</li>'}<li>${pages.length} 个画面 · ${sentences.length} 句文案</li><li>${missing?'⚠ '+missing+' 句尚无最新配音':'✓ 所有英文句子已配音'}</li><li>${untranslated?'○ '+untranslated+' 句尚未填写中文翻译':'✓ 中文字幕已填写'}</li><li>发布后生成独立版本，后续修改进入新草稿</li></ul>${missing?'<p class="hint warning notice">请先完成英文配音与中文字幕，之后再发布。纯插画页可以不添加句子。</p>':''}<div class="modal-actions"><button data-close>继续制作</button><button class="primary" id="publishConfirm" ${errors.length?'disabled':''}>确认发布到本地</button></div>`);$('#publishConfirm').onclick=async()=>{try{await flush();const next=store.publishBook(book);book=await store.saveBook(next);closeModal();saveError=null;await refreshBooks();book=null;renderLibrary();toast('已发布到本地书库；线上内容未改变')}catch(e){fail(e)}}}
async function manage(target=book){if(working)return toast('请先完成当前处理');showModal(`<h2>管理绘本可见范围</h2><p class="muted">${escape(target.title)} · 当前${names[target.status]}</p><ul class="checklist"><li><b>上架</b>　显示在本地书库，可打开发布版本。</li><li><b>隐藏</b>　从阅读书架隐藏，保留已有访问入口。</li><li><b>下架</b>　停止阅读入口，保留内容供后续重新上架。</li></ul><p class="hint">当前只模拟本地状态，尚未连接阅读端和私有归档。</p><div class="modal-actions"><button data-close>取消</button><button id="statusHidden">隐藏</button><button id="statusWithdrawn" class="danger">下架</button><button id="statusPublished" class="primary">重新上架</button></div>`);for(const [id,status]of[['statusHidden','hidden'],['statusWithdrawn','withdrawn'],['statusPublished','published']])$('#'+id).onclick=async()=>{try{if(target===book)await flush();const saved=await store.saveBook(store.setStatus(target,status));if(target===book)book=saved;closeModal();await refreshBooks();render();toast(`${names[status]}（本地）`)}catch(e){fail(e)}}}
async function addSample(){const target=book;if(working)return toast('请先完成当前处理');showModal(`<h2>添加公开示例图片</h2><p class="hint">仅供本地体验，使用现有公开样本；不会自动生成文字或配音。</p><div class="form-grid">${[['p01','封面'],['p04','普通双页'],['p08','艺术字页'],['p18','密集文字页']].map(([id,label])=>`<button data-sample="${id}"><img style="width:100%;height:100px;object-fit:contain" src="../ipad-ocr-test/samples/${id}.jpeg">${label}</button>`).join('')}</div><div class="modal-actions"><button data-close>取消</button></div>`);document.querySelectorAll('[data-sample]').forEach(el=>el.onclick=async()=>{try{const res=await fetch(`../ipad-ocr-test/samples/${el.dataset.sample}.jpeg`);if(!res.ok)throw new Error('示例图片加载失败');const blob=await res.blob();if(book!==target)throw new Error('绘本已切换，请重新添加示例图片');closeModal();await acceptImages([new File([blob],`${el.dataset.sample}.jpeg`,{type:'image/jpeg'})]);toast('示例图片已添加')}catch(e){fail(e)}})}
const actions={imageWorkspace:()=>setWorkspace('image'),textWorkspace:()=>setWorkspace('text'),audioWorkspace:()=>setWorkspace('audio'),pageTTS,nextPendingPage,providerConfig,multimodalCorners,analyzePage,importAnalysis,exportAnalysis,reviewPage,stopRegion:()=>{regionMode=false;regionDraft=null;render();revealSentence(selectedSentenceId)},confirmRectification:async()=>{if(working)return;const p=currentPage();p.rectificationReviewed=true;p.rectificationRevision=p.imageRevision||0;editorMode='text';job='';await persist();render();toast('已人工确认当前图像可用')},detectBorder,applyBorder,manualBorder:()=>{if(working)return;const p=currentPage();if(!p)return;perspective={pageId:p.id,image:p.image,corners:[{x:.05,y:.05},{x:.95,y:.05},{x:.95,y:.95},{x:.05,y:.95}],method:'手动选区',needsManual:true,warning:'拖动四角到书页边缘，候选尚未应用。'};render()},cancelBorder:()=>{perspective=null;render()},sample:addSample,new:create,library,cover:()=>$('#coverFile').click(),import:()=>$('#imageFiles').click(),replace:()=>$('#replaceFile').click(),previewDraft:async()=>{if(!book.draft){book=store.beginEdit(book);await persist()}tab='preview';previewSource='draft';readerPage=0;readerSentence=0;render()},previewPublished:()=>{tab='preview';previewSource='published';readerPage=0;readerSentence=0;render()},publish,manage:()=>manage(),batchOCR:()=>ocrAction(true),ocr:()=>ocrAction(false),batchTTS,pause:()=>{pause=true;setJob('暂停请求已接收，当前页 / 句完成后停止')},clearCrop:()=>{crop={x:0,y:0,w:100,h:100};render()},addSentence:async()=>{const p=currentPage();if(working||!rectified(p))return toast('请先确认校正图');editorMode='text';const newSentenceId=uid('sentence');selectedSentenceId=newSentenceId;p.sentences.push({id:newSentenceId,en:'',zh:'',regions:[],kind:'narration',includeInNarration:true,reviewed:false,anchorRevision:p.imageRevision||0,audio:null,audioText:''});p.analysisReviewed=false;p.textRevision=(p.textRevision||0)+1;await persist();render()},deleteBook:()=>working?toast('请先完成当前处理'):confirmAction('删除这本绘本？','这会删除当前浏览器中的草稿和发布版本，无法撤销。建议先导出备份。',async()=>{await flush();await store.deleteBook(book.id);book=null;await refreshBooks();render();toast('本地绘本已删除')},'确认删除'),readerPrev:()=>{readerPage=Math.max(0,readerPage-1);readerSentence=0;render()},readerNext:()=>{const snap=previewSource==='published'?book.published:book.draft;readerPage=Math.min(snap.pages.length-1,readerPage+1);readerSentence=0;render()},readerPlay:playReader,readerStop:stopReader};
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-open],[data-preview],[data-manage]');if(!el)return;try{if(el.hasAttribute('data-close'))return closeModal();if(el.dataset.act){if(actions[el.dataset.act])await actions[el.dataset.act]();else await pageAction(el.dataset.act)}else if(el.dataset.open)await openBook(el.dataset.open);else if(el.dataset.preview){await openBook(el.dataset.preview,'preview');previewSource='published';render()}else if(el.dataset.manage){await flush();await manage(await store.getBook(el.dataset.manage))}else if(el.dataset.filter){filter=el.dataset.filter;renderLibrary()}else if(el.dataset.tab){await flush();if(!book.draft&&el.dataset.tab!=='preview'){book=store.beginEdit(book);await persist();pageId=book.draft.pages[0]?.id}tab=el.dataset.tab;render()}else if(el.dataset.mode){setWorkspace(el.dataset.mode)}else if(el.dataset.page){if(working)return toast('请等待当前处理完成');await flush();pageId=el.dataset.page;editorMode='auto';job='';returnToAudioSentenceId=null;ttsActivity=null;perspective=null;selectedSentenceId=null;regionMode=false;regionDraft=null;crop={x:0,y:0,w:100,h:100};render()}else if(el.dataset.sact)await sentenceAction(el.dataset.sact,el.dataset.sid);else if(el.dataset.source){previewSource=el.dataset.source;readerPage=0;readerSentence=0;render()}}catch(e){fail(e)}});
$('#libraryNav').onclick=()=>library().catch(fail);$('#newNav').onclick=()=>create().catch(fail);$('.brand').onclick=e=>{e.preventDefault();library().catch(fail)};
$('#imageFiles').onchange=async e=>{try{await acceptImages(e.target.files)}catch(e){fail(e)}e.target.value=''};$('#replaceFile').onchange=async e=>{try{await acceptImages(e.target.files,'replace')}catch(e){fail(e)}e.target.value=''};$('#coverFile').onchange=async e=>{try{await acceptImages(e.target.files,'cover')}catch(e){fail(e)}e.target.value=''};
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),30000)}
$('#exportBackup').onclick=async()=>{try{await flush();const data=await store.exportBackup();download(new Blob([JSON.stringify(data)],{type:'application/json'}),`绘本工作室备份-${new Date().toISOString().slice(0,10)}.json`);toast('备份已准备，请确认浏览器下载结果')}catch(e){fail(e)}};
$('#importBackup').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(working)return toast('请先完成当前处理再导入备份');try{const data=JSON.parse(await file.text());await confirmAction('导入工作室备份？','将恢复备份中的绘本到当前浏览器。同一编号的绘本会被备份覆盖，其他绘本保留。请先导出当前内容。',async()=>{if(working)return toast('请先完成当前处理再导入备份');await flush();const result=await store.importBackup(data);book=null;await refreshBooks();render();toast(`备份导入完成`)} ,'导入备份')}catch(e){fail(e)}e.target.value=''};
window.addEventListener('beforeunload',e=>{if(saveTimer||pendingWrites||working){e.preventDefault();e.returnValue=''}});
(async()=>{try{await credentials.restore().catch(()=>{});await store.init();await refreshBooks();renderLibrary();checkProvider()}catch(e){app.innerHTML=`<div class="empty"><h2>本地存储暂不可用</h2><p>${escape(e.message)}</p><p>请使用正常浏览模式并允许浏览器保存网站数据。</p></div>`;fail(e)}})();

document.addEventListener('visibilitychange',()=>{if(document.hidden&&working){pause=true;setJob('页面进入后台，当前页 / 句完成后暂停；回来后可继续')}});

$('#saveState').onclick=()=>{if(saveError&&book)persist().then(()=>toast('本地保存成功')).catch(fail)};

window.addEventListener('resize',()=>updateReaderSize?.());

$('#settingsNav').onclick=()=>providerConfig().catch(fail);
credentials.subscribe(event=>{checkProvider();if(modal.open&&modal.classList.contains('settings-modal')){const status=$('#credentialsStatus');if(status)status.textContent=settingsStateText();if(!event.unlocked){const fields=$('#connectionFields');if(fields)fields.disabled=true;for(const id of ['modelToken','cosSecretId','cosSecretKey','vaultPassword','vaultPasswordAgain','newVaultPassword','newVaultPasswordAgain','vaultUnlockPassword','configurationSourcePassword','configurationNewPassword','configurationNewPasswordAgain','configurationCurrentPassword']){const input=$('#'+id);if(input)input.value=''}if(event.reason==='changed'){const text=$('#configurationText');if(text)text.value='';const preview=$('#configurationPreview');if(preview)preview.innerHTML='';$('#modalBody').dataset.invalidated='true';const save=$('#saveCredentials');if(save)save.disabled=true;const error=$('#settingsError');if(error)error.textContent='其他标签页更改了配置，请关闭后重新打开设置并解锁。'}}}});
modal.addEventListener('cancel',event=>{if(modal.classList.contains('settings-modal')){event.preventDefault();closeModal()}});
